"""Work out who acts, and in which order, in a round of combat (tabletop initiative)."""

SIDE_RANK = {"players": 0, "allies": 1, "foes": 2}


def _base_scores(combatants):
    """Initiative score is the d20 roll plus the dexterity modifier."""
    entries = []
    for c in combatants:
        modifier = (c["dex"] - 10) // 2
        entries.append({"name": c["name"], "score": c["roll"] + modifier, "dex": c["dex"], "side": c["side"],
                        "conditions": list(c.get("conditions", []))})
    return entries


def _apply_conditions(entries):
    """Stunned combatants lose the round; haste and slow shift the score."""
    skipped = []
    active = []
    for e in entries:
        if "stunned" in e["conditions"]:
            skipped.append(e["name"])
            continue
        if "hasted" in e["conditions"]:
            e["score"] += 5
        if "slowed" in e["conditions"]:
            e["score"] -= 2
        active.append(e)
    entries = active
    return entries, skipped


def _surprise_bonus(entries, round_no):
    """Ambushing players act earlier in the first round."""
    if round_no == 1:
        for e in entries:
            if e["side"] == "players" and "ambush" in e["conditions"]:
                e["score"] += 10
    return entries


def _split_delayed(entries):
    """Combatants who are delaying go after everyone else."""
    delayed = [e for e in entries if "delaying" in e["conditions"]]
    entries = [e for e in entries if "delaying" not in e["conditions"]]
    return entries, delayed


def _sort_entries(entries):
    """Highest score first; ties go to higher dexterity, then players before allies before foes, then name."""
    entries = sorted(entries, key=lambda e: (-e["score"], -e["dex"], SIDE_RANK[e["side"]], e["name"]))
    return entries


def _limit_actions(entries, skipped):
    """Only the first few combatants act; the rest are listed as skipped."""
    if len(entries) > 6:
        for e in entries[6:]:
            skipped.append(e["name"])
        entries = entries[:6]
    return entries


def turn_order(combatants, round_no):
    """Work out who acts, and in which order, in a round of combat."""
    entries = _base_scores(combatants)
    entries, skipped = _apply_conditions(entries)
    entries = _surprise_bonus(entries, round_no)
    entries, delayed = _split_delayed(entries)
    entries = _sort_entries(entries)
    entries = _limit_actions(entries, skipped)
    order = [e["name"] for e in entries] + [e["name"] for e in delayed]
    return {"order": order, "skipped": skipped}

