def body_without_doc(fn):
    body = list(fn.body)
    if body and isinstance(body[0], ast.Expr) and isinstance(getattr(body[0], "value", None), ast.Constant) \
            and isinstance(body[0].value.value, str):
        body = body[1:]
    return body


def duplicate_functions(files, min_stmts=4):
    """Groups of functions (across files) whose bodies have the same shape and at least min_stmts statements."""
    seen = {}
    for rel in files:
        tree = parse(rel)
        for q, fn in functions(tree):
            body = body_without_doc(fn)
            if stmt_count(body) < min_stmts:
                continue
            seen.setdefault(fingerprint(body), []).append(rel + ":" + q)
    return [v for v in seen.values() if len(v) > 1]


def repeated_windows(files, k=4):
    """Number of distinct k-statement sequences (shape only) that occur more than once, across all bodies."""
    seen = {}
    for rel in files:
        tree = parse(rel)
        for node in ast.walk(tree):
            for field in ("body", "orelse", "finalbody"):
                stmts = getattr(node, field, None)
                if not isinstance(stmts, list) or len(stmts) < k:
                    continue
                if not all(isinstance(s, ast.stmt) for s in stmts):
                    continue
                for i in range(len(stmts) - k + 1):
                    win = stmts[i:i + k]
                    if stmt_count(win) < k + 2:
                        continue
                    key = fingerprint(win)
                    seen.setdefault(key, set()).add((rel, win[0].lineno))
    return sum(1 for v in seen.values() if len(v) > 1)


def imports(rel):
    """Names of modules imported by a file (dotted, as written; relative imports resolved against the file)."""
    tree = parse(rel)
    pkg = os.path.dirname(rel).replace("/", ".")
    out = set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            out.update(a.name for a in n.names)
        elif isinstance(n, ast.ImportFrom):
            base = n.module or ""
            if n.level:
                parts = pkg.split(".") if pkg else []
                parts = parts[: len(parts) - (n.level - 1)] if n.level > 1 else parts
                base = ".".join(p for p in parts + ([n.module] if n.module else []) if p)
                for a in n.names:
                    out.add(base + "." + a.name if base else a.name)
            if base:
                out.add(base)
            if not n.level:
                for a in n.names:
                    out.add(base + "." + a.name)
    return out


def module_name(rel):
    m = rel[:-3].replace("/", ".")
    return m[: -len(".__init__")] if m.endswith(".__init__") else m


def import_cycles(files):
    """Cycles in the import graph restricted to the given project files (module names)."""
    mods = {module_name(f): f for f in files}
    graph = {}
    for name, rel in mods.items():
        deps = set()
        for imp in imports(rel):
            parts = imp.split(".")
            for i in range(len(parts), 0, -1):
                cand = ".".join(parts[:i])
                if cand in mods and cand != name:
                    deps.add(cand)
                    break
        graph[name] = deps
    cycles = []
    state = {}

    def dfs(n, stack):
        state[n] = 1
        for m in sorted(graph.get(n, ())):
            if state.get(m) == 1:
                cycles.append(stack[stack.index(m):] + [m] if m in stack else [n, m])
            elif m not in state:
                dfs(m, stack + [m])
        state[n] = 2

    for n in sorted(graph):
        if n not in state:
            dfs(n, [n])
    return cycles


def top_level_names(tree):
    out = set()
    for n in tree.body:
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            out.add(n.name)
        elif isinstance(n, ast.Assign):
            for t in n.targets:
                for x in ast.walk(t):
                    if isinstance(x, ast.Name):
                        out.add(x.id)
    return out


def called_names(node):
    out = []
    for n in ast.walk(node):
        if isinstance(n, ast.Call):
            f = n.func
            if isinstance(f, ast.Name):
                out.append(f.id)
            elif isinstance(f, ast.Attribute):
                out.append(f.attr)
    return out


def dotted_calls(node):
    """Dotted call targets such as time.time or datetime.datetime.now."""
    out = []
    for n in ast.walk(node):
        if isinstance(n, ast.Call):
            parts = []
            f = n.func
            while isinstance(f, ast.Attribute):
                parts.append(f.attr)
                f = f.value
            if isinstance(f, ast.Name):
                parts.append(f.id)
                out.append(".".join(reversed(parts)))
    return out


def format_problems(problems):
    return "\n".join("  - " + p for p in problems)


_MUTATORS = {"append", "extend", "add", "update", "pop", "popitem", "clear", "setdefault", "remove", "insert", "discard", "sort", "reverse"}
_CONTAINER_CALLS = {"dict", "list", "set", "defaultdict", "Counter", "OrderedDict", "deque", "bytearray"}


def global_state_problems(tree):
    """Module-level containers that functions mutate, and `global` statements: the signs of hidden shared state."""
    containers = set()
    for n in tree.body:
        if isinstance(n, ast.Assign):
            v = n.value
            is_container = isinstance(v, (ast.Dict, ast.List, ast.Set, ast.ListComp, ast.DictComp, ast.SetComp))
            if isinstance(v, ast.Call):
                f = v.func
                name = f.id if isinstance(f, ast.Name) else f.attr if isinstance(f, ast.Attribute) else ""
                is_container = name in _CONTAINER_CALLS
            if is_container:
                for t in n.targets:
                    if isinstance(t, ast.Name):
                        containers.add(t.id)
    problems = []
    for q, fn in functions(tree):
        for node in ast.walk(fn):
            if isinstance(node, ast.Global):
                problems.append("%s uses `global %s`" % (q, ", ".join(node.names)))
            elif isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr in _MUTATORS \
                    and isinstance(node.func.value, ast.Name) and node.func.value.id in containers:
                problems.append("%s mutates module-level %s" % (q, node.func.value.id))
            elif isinstance(node, (ast.Assign, ast.AugAssign, ast.Delete)):
                targets = node.targets if isinstance(node, (ast.Assign, ast.Delete)) else [node.target]
                for t in targets:
                    if isinstance(t, ast.Subscript) and isinstance(t.value, ast.Name) and t.value.id in containers:
                        problems.append("%s writes into module-level %s" % (q, t.value.id))
    return sorted(set(problems))

