"""Work out who acts, and in which order, in a round of combat (tabletop initiative)."""

SIDE_RANK = {"players": 0, "allies": 1, "foes": 2}


def turn_order(combatants, round_no):
    """Work out who acts, and in which order, in a round of combat."""
    # --- base initiative scores ---
    entries = []
    for c in combatants:
        modifier = (c["dex"] - 10) // 2
        entries.append({"name": c["name"], "score": c["roll"] + modifier, "dex": c["dex"], "side": c["side"],
                        "conditions": list(c.get("conditions", []))})

    # --- condition handling ---
    skipped = []
    active = []
    for e in entries:
        if "stunned" in e["conditions"]:
            skipped.append(e["name"])
            continue
        if "hasted" in e["conditions"]:
            e["score"] += 3
        if "slowed" in e["conditions"]:
            e["score"] -= 3
        active.append(e)
    entries = active

    # --- surprise-round bonus ---
    if round_no == 1:
        for e in entries:
            if e["side"] == "players" and "ambush" in e["conditions"]:
                e["score"] += 5

    # --- delayed turns ---
    delayed = [e for e in entries if "delaying" in e["conditions"]]
    entries = [e for e in entries if "delaying" not in e["conditions"]]

    # --- tie-break sorting ---
    entries = sorted(entries, key=lambda e: (-e["score"], -e["dex"], SIDE_RANK[e["side"]], e["name"]))

    order = [e["name"] for e in entries] + [e["name"] for e in delayed]
    return {"order": order, "skipped": skipped}

