"""Turn raw intake lines into the list of samples to shelve and the list of rejects (lab sample intake)."""

SHELF_LIFE_DAYS = {
    "buffy": 14,
    "stool": 13,
    "swab": 4,
    "saliva": 9,
    "serum": 11,
}

UNIT_FOR_KIND = {
    "buffy": "F3",
    "stool": "F1",
    "swab": "F2",
    "saliva": "F3",
    "serum": "F3",
}

UNIT_CAPACITY = {"F1": 4, "F2": 2, "F3": 3}


def _parse_lines(raw_lines, today):
    """Split the raw lines into sample records; lines that cannot be read go to the rejected list."""
    rows = []
    rejected = []
    for number, line in enumerate(raw_lines, 1):
        parts = [p.strip() for p in line.split(";")]
        if len(parts) != 4:
            rejected.append("line %d: expected 4 fields" % number)
            continue
        sample_id, kind, received, priority = parts
        if kind not in SHELF_LIFE_DAYS:
            rejected.append("line %d: unknown kind %s" % (number, kind))
            continue
        try:
            age = today - int(received)
            prio = int(priority)
        except ValueError:
            rejected.append("line %d: bad number" % number)
            continue
        rows.append({"id": sample_id, "kind": kind, "age": age, "priority": prio})
    return rows, rejected


def _drop_repeats(rows, rejected):
    """Keep only the first record of each sample id."""
    seen = set()
    unique = []
    for row in rows:
        if row["id"] in seen:
            rejected.append("%s: duplicate id" % row["id"])
            continue
        seen.add(row["id"])
        unique.append(row)
    rows = unique
    return rows


def _drop_expired(rows, rejected):
    """Reject samples older than the shelf life of their kind."""
    fresh = []
    for row in rows:
        if row["age"] > SHELF_LIFE_DAYS[row["kind"]]:
            rejected.append("%s: expired (%d days)" % (row["id"], row["age"]))
        else:
            fresh.append(row)
    rows = fresh
    return rows


def _bump_rush(rows):
    """Bump the priority of fresh samples of the rush kind."""
    for row in rows:
        if row["kind"] == "swab" and row["age"] <= 1:
            row["priority"] += 5


def _order_batch(rows):
    """Order by priority (high first), then freshest first, then id."""
    rows = sorted(rows, key=lambda r: (-r["priority"], r["age"], r["id"]))
    return rows


def _cap_batch(rows, rejected):
    """Process at most one batch; the rest is deferred."""
    if len(rows) > 5:
        for row in rows[5:]:
            rejected.append("%s: deferred to next batch" % row["id"])
        rows = rows[:5]
    return rows


def _assign_units(rows, rejected):
    """Give every sample the fridge unit for its kind; full units turn samples away."""
    load = {}
    placed = []
    for row in rows:
        unit = UNIT_FOR_KIND[row["kind"]]
        if load.get(unit, 0) >= UNIT_CAPACITY[unit]:
            rejected.append("%s: unit %s is full" % (row["id"], unit))
            continue
        load[unit] = load.get(unit, 0) + 1
        row["unit"] = unit
        placed.append(row)
    rows = placed
    return rows


def plan_intake(raw_lines, today):
    """Turn raw intake lines into the list of samples to shelve and the list of rejects."""
    rows, rejected = _parse_lines(raw_lines, today)
    rows = _drop_repeats(rows, rejected)
    rows = _drop_expired(rows, rejected)
    _bump_rush(rows)
    rows = _order_batch(rows)
    rows = _cap_batch(rows, rejected)
    rows = _assign_units(rows, rejected)
    labels = ["%s|%s|%s|p%d" % (r["id"], r["kind"], r["unit"], r["priority"]) for r in rows]
    return {"labels": labels, "rejected": rejected}

